// Turns the SOURCES tab the pitching engine already maintains into CrowdRelay
// candidates. It imports what the band worked out by hand; it does not decide
// who may be contacted. Screening still judges every row on the CrowdRelay
// side, and an operator still confirms each route before it becomes a target.
//
// Three rules keep this honest:
//
//  - `route_is_published` is true only where the row records a route. A blank
//    cell is skipped, never turned into an address by guessing at a domain.
//  - `PROFILE_TASK` rows are not outreach. They are jobs on our own artist
//    profiles, and importing them as contacts would put housekeeping into a
//    queue meant for people.
//  - Prior contact is read from SUBMISSION_LOG, not from the SOURCES row.
//    `Last_Pitched_At` on SOURCES is never backfilled — it is empty on every
//    row while the log holds thirteen sends to eight curators. Trusting the
//    column would hand those eight over as untouched first approaches, and the
//    band only gets one of those per curator.

function clean(v) { return String(v === undefined || v === null ? '' : v).trim(); }
function truth(v) { return ['TRUE','YES','TAK','1'].includes(clean(v).toUpperCase()); }
function isEmail(v) { return /^[^\s@,;]+@[^\s@,;]+\.[^\s@,;]+$/.test(clean(v).toLowerCase()); }

// Where a submission actually lands. Everything here is a playlist route today;
// the column is kept so a future radio or press row maps without a code change.
const KIND = { spotify: 'playlist', deezer: 'playlist', tidal: 'playlist',
               'apple music': 'playlist', 'amazon music': 'playlist',
               multi: 'playlist', radio: 'radio', press: 'press', creator: 'creator' };

function rowsOf(node) { try { return $(node).all().map(i => i.json || {}); } catch (e) { return []; } }
const rows = rowsOf('GS — SOURCES');

// Everyone already contacted, by address and by source. The log is the only
// honest record of this: SOURCES.Last_Pitched_At was never written back.
const contactedEmail = new Set();
const contactedSource = new Set();
for (const log of rowsOf('GS — SUBMISSION_LOG')) {
  const recipient = clean(log.Recipient).toLowerCase();
  const sourceId = clean(log.Source_ID).toUpperCase();
  if (recipient) contactedEmail.add(recipient);
  if (sourceId) contactedSource.add(sourceId);
}
const candidates = [];
const skipped = { inactive: 0, profile_task: 0, no_route: 0 };
let already = 0;

for (const row of rows) {
  const id = clean(row.Source_ID);
  if (!id) continue;
  if (!truth(row.Active)) { skipped.inactive += 1; continue; }

  const actionClass = clean(row.Action_Class).toUpperCase();
  // A task on our own profile is not a contact.
  if (actionClass === 'PROFILE_TASK') { skipped.profile_task += 1; continue; }

  const email = clean(row.Contact_Email);
  const form = clean(row.Submission_URL);
  let route_kind = null, route_value = null;
  if (isEmail(email)) { route_kind = 'email'; route_value = email.toLowerCase(); }
  else if (/^https?:\/\//i.test(form)) { route_kind = 'submission_form'; route_value = form; }
  if (!route_value) { skipped.no_route += 1; continue; }

  const priorSend = contactedEmail.has(route_value.toLowerCase())
    || contactedSource.has(id.toUpperCase());
  if (priorSend) already += 1;

  const platform = clean(row.Platform).toLowerCase().split('/')[0].trim();
  const evidenceUrl = clean(row.Source_Evidence_URL);

  candidates.push({
    target_kind: KIND[platform] || 'playlist',
    display_name: (clean(row.Source_Name) || id).slice(0, 200),
    source: 'operator_import',
    source_reference: (evidenceUrl || ('sheet:' + clean($env.VIRYA_PITCHING_SHEET_ID) + '#SOURCES:' + id)).slice(0, 2048),
    // The row itself is the evidence for an import: what was recorded, when it
    // was last verified, and whether the one first approach is already spent.
    evidence: ('Operator import from PLAYLIST_PITCHING SOURCES, row ' + id + '. '
      + 'Platform: ' + (clean(row.Platform) || 'unknown') + '. '
      + 'Recorded action class: ' + (actionClass || 'unset') + '. '
      + 'Free channel: ' + (truth(row.Free) ? 'yes' : 'no') + '. '
      + 'Last verified: ' + (clean(row.Last_Verified) || 'never') + '. '
      + (priorSend
          ? 'ALREADY PITCHED by the sheet-driven engine (see SUBMISSION_LOG); the first approach is spent.'
          : 'No prior pitch recorded in SUBMISSION_LOG.')
      + (clean(row.Notes) ? ' Notes: ' + clean(row.Notes) : '')).slice(0, 4000),
    route_kind,
    route_value: route_value.slice(0, 2048),
    route_is_published: true,
    // The sheet's own scores are the band's judgement of fit, not a measurement.
    // Where it has one, use it; otherwise fall back rather than invent a number.
    fit_basis_points: (function () {
      const trust = Number(clean(row.Trust_Score));
      return Number.isFinite(trust) && trust > 0
        ? Math.max(0, Math.min(10000, Math.round(trust * 100)))
        : Number($env.VIRYA_IMPORT_FIT_BASIS_POINTS || 7000);
    })(),
    follower_count: null,
    engagement_count: null,
    // Both stay false: a spreadsheet cannot support either claim, and guessing
    // one would refuse a real contact on evidence we do not have.
    sells_placement: false,
    churns_indiscriminately: false
  });
}

const seen = new Set();
const unique = candidates.filter(c => {
  const key = c.route_kind + ':' + c.route_value.toLowerCase();
  if (seen.has(key)) return false;
  seen.add(key); return true;
});

const batches = [];
for (let i = 0; i < unique.length; i += 100) batches.push(unique.slice(i, i + 100));

return [{ json: {
  commit: truth($env.VIRYA_IMPORT_COMMIT),
  total: unique.length,
  already,
  emails: unique.filter(c => c.route_kind === 'email').length,
  forms: unique.filter(c => c.route_kind === 'submission_form').length,
  skipped,
  batches,
  preview: unique.slice(0, 5).map(c => c.display_name)
}}];

// Dry run by default. An import that writes on its first execution gives nobody
// a chance to read what it matched, and a wrong mapping is far cheaper to find
// in a report than in a queue of contacts nobody recognises.
const r = $json;
const lines = [
  '**VIRYA — import kontaktow z PLAYLIST_PITCHING**',
  '',
  r.commit ? 'Tryb: ZAPIS do CrowdRelay' : 'Tryb: PROBNY (nic nie zapisano)',
  'Do zaimportowania: ' + r.total + ' (' + r.emails + ' e-mail, ' + r.forms + ' formularz)',
  'Juz pitchowane wczesniej: ' + r.already + ' — pierwsze podejscie zuzyte',
  'Pominiete — nieaktywne: ' + r.skipped.inactive,
  'Pominiete — zadanie na wlasnym profilu: ' + r.skipped.profile_task,
  'Pominiete — brak zapisanej sciezki kontaktu: ' + r.skipped.no_route,
  '',
  'Przyklady: ' + r.preview.join(', ')
];
if (!r.commit) lines.push('', 'Ustaw VIRYA_IMPORT_COMMIT=TRUE i uruchom ponownie, aby zapisac.');
const content = lines.join('\n').slice(0, 1900);
// Pre-serialised: an n8n expression cannot carry a nested object literal,
// because its parser stops at the first `}}`.
const discordBody = JSON.stringify({ content, allowed_mentions: { parse: [] } });
return [{ json: { content, discordBody } }];
